-- (3) 관리자 목록 순서를 축별로 다시 매긴다 (홈 순서는 브라우저가 섞는다)
with o as (select id, row_number() over (order by case grp when '연애' then 1 when '결혼' then 2 when '일' then 3 when '돈' then 4 when '삶' then 5 when '나·시기' then 6 else 9 end, sort, created_at) rn from public.home_topics)
update public.home_topics h set sort = o.rn from o where o.id = h.id;
